mapper.sql:
  FROM golf.reservation r
  JOIN golf.member m ON m.member_id = r.member_id
  LEFT JOIN golf.tee_time t ON t.tee_time_id = r.tee_time_id
  LEFT JOIN golf.golf_course gc ON gc.golf_course_id = COALESCE(r.golf_course_id, t.golf_course_id)


		AND (r.reservation_no ILIKE CONCAT('%', #{keyword}, '%')
		  OR m.member_name ILIKE CONCAT('%', #{keyword}, '%')
		  OR m.phone LIKE CONCAT('%', #{keyword}, '%'))

	AND r.reservation_status = #{status}
	AND COALESCE(r.golf_course_id, t.golf_course_id) = #{courseId}
	AND r.member_id = #{memberId}
	AND COALESCE(r.play_at, t.play_date + t.start_time) >= #{playFrom}
	AND COALESCE(r.play_at, t.play_date + t.start_time) < #{playTo}
